    LANGUAGE_WRAPPER = 'A circle C of radius {radius} contains two concentric rings of {n} congruent circles each. The outer ring’s circles are internally tangent to C and externally tangent to their two adjacent neighbors. The inner ring’s circles are externally tangent to a central circle D (concentric with C) and externally tangent to their two adjacent neighbors. Moreover, each circle in the outer ring is externally tangent to exactly one circle in the inner ring along the same radial line through the common center. Let K be the area of the region inside C and outside all 2{n} ring circles and the central circle D. Compute floor(K).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

